export const PHOTO_ASSET_BY_SLUG: Record<string, PhotoAsset> = Object.fromEntries(
  PHOTO_ASSETS.map((asset) => [asset.slug, asset]),
);

/** Path of a responsive variant, e.g. `/images/garden-beds-960.webp`. */
export function photoVariantPath(asset: PhotoAsset, width: number): string {
  return `/images/${asset.slug}-${width}.webp`;
}

/**
 * WebP `srcSet`, narrowest first, always ending on the full-size frame so the
 * browser never has to interpolate a rung that was not actually generated.
 */
export function photoWebpSrcSet(asset: PhotoAsset): string {
  const rungs = [...asset.variants]
    .sort((a, b) => a - b)
    .filter((width) => width < asset.width)
    .map((width) => `${photoVariantPath(asset, width)} ${width}w`);
  rungs.push(`${asset.webp} ${asset.width}w`);
  return rungs.join(", ");
}

/**
 * JPEG fallback `srcSet`. Responsive variants are WebP only, so this is a
 * single rung; it exists for browsers with no WebP support.
 */
export function photoJpegSrcSet(asset: PhotoAsset): string {
  return `${asset.jpeg} ${asset.width}w`;
}

/** CSS `aspect-ratio` value, so containers reserve exact space and never shift. */
export function photoAspectRatio(asset: PhotoAsset): string {
  return `${asset.width} / ${asset.height}`;
}

/** Looks an asset up by slug and fails loudly instead of rendering a broken image. */
export function photo(slug: string): PhotoAsset {
  const asset = PHOTO_ASSET_BY_SLUG[slug];
  if (!asset) throw new Error(`Unknown photo asset slug: ${slug}`);
  return asset;
}

/** Portrait pool for the neutral cards, rails and grids in docs/PHOTO_USAGE_PLAN.md. */
export const PORTRAIT_PHOTO_ASSETS = PHOTO_ASSETS.filter((asset) => asset.orientation === "portrait");

/** Landscape pool — the only frames safe for wide slots. */
export const LANDSCAPE_PHOTO_ASSETS = PHOTO_ASSETS.filter((asset) => asset.orientation === "landscape");
